import * as cheerio from "cheerio";
import type { FeedConfig, FeedItem, ScraperHelpers } from "../../types.js";

export async function fetchFeed(
  config: FeedConfig,
  helpers: ScraperHelpers
): Promise<FeedItem[]> {
  // 1. Fetch the listing page
  const listingHtml = await fetch(config.url).then((r) => r.text());
  const $ = cheerio.load(listingHtml);

  // 2. Parse all card items from the listing
  const cards: Array<{
    id: string;
    title: string;
    url: string;
    publishedAt: string;
  }> = [];

  $(".card_blog_wrap").each((_i, el) => {
    const card = $(el);
    const link = card.find('a[href*="/blog/"]').first();
    const href = link.attr("href") || "";
    if (!href) return;

    const url = href.startsWith("http") ? href : `https://claude.com${href}`;
    const title = card.find(".card_blog_title").first().text().trim();
    if (!title) return;

    const dateText = card.find(".u-text-style-caption").first().text().trim();
    const parsed = new Date(dateText);
    const publishedAt = isNaN(parsed.getTime()) ? new Date().toISOString() : parsed.toISOString();

    // Derive a stable ID from the URL slug
    const slug = href.split("/").filter(Boolean).pop() || url;
    const id = slug || url;

    cards.push({ id, title, url, publishedAt });
  });

  // 3. Fetch each detail page in parallel to get imageUrl & contentHtml
  const detailResults = await Promise.all(
    cards.map(async (card) => {
      try {
        const html = await fetch(card.url).then((r) => r.text());
        const $detail = cheerio.load(html);

        // --- imageUrl: first og:image that is NOT the generic fallback ---
        let imageUrl: string | undefined;
        const ogImages = $detail('meta[property="og:image"]');
        ogImages.each((_i, el) => {
          const content = $detail(el).attr("content") || "";
          if (content && !content.includes("og_claude-generic") && !imageUrl) {
            imageUrl = content;
          }
        });

        // --- contentHtml: full inner HTML of .u-rich-text-blog ---
        const rte = $detail(".u-rich-text-blog").first();
        const contentHtml = rte.length > 0 ? rte.html() ?? undefined : undefined;

        return { imageUrl, contentHtml };
      } catch {
        // Gracefully degrade if a single detail fetch fails
        return { imageUrl: undefined, contentHtml: undefined };
      }
    })
  );

  // 4. Assemble final FeedItem array
  return cards.map((card, i) => {
    const detail = detailResults[i] ?? { imageUrl: undefined, contentHtml: undefined };

    const item: FeedItem = {
      id: card.id,
      title: card.title,
      url: card.url,
      publishedAt: card.publishedAt,
      source: config.slug,
    };

    if (detail.imageUrl) {
      item.imageUrl = detail.imageUrl;
    }

    if (detail.contentHtml) {
      item.contentHtml = detail.contentHtml;
    }

    return item;
  });
}
